        c.withdraw(withdrawAmount);

        // Rule: caller's final balance = balanceAfterDeposit + withdrawAmount
        // In reference: transfer sends withdrawAmount, so final = balanceAfterDeposit + withdrawAmount
        // In bug: transfer sends 0, so final = balanceAfterDeposit
        assertTrue(caller.balance == balanceAfterDeposit + withdrawAmount);
    }
}

