pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 depositAmount) public {
        vm.assume(amount > 0 && amount <= type(uint256).max);
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max);

        // Deposit some ETH first
        vm.deal(address(this), depositAmount);
        c.deposit{value: depositAmount}();

        // Get balances before withdrawal
        uint256 contractBalanceBefore = address(c).balance;
        uint256 callerBalanceBefore = c.balances(address(this));

        // Perform withdrawal of amount (ensuring it's valid)
        vm.assume(amount <= callerBalanceBefore);

        // Wrap withdrawal in try/catch to handle revert
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After withdrawal (if it succeeded), contract balance decreased by amount, caller balance decreased by amount => sum unchanged
        uint256 contractBalanceAfter;
        uint256 callerBalanceAfter;
        if (!reverted) {
            contractBalanceAfter = address(c).balance;
            callerBalanceAfter = c.balances(address(this));
        } else {
            contractBalanceAfter = contractBalanceBefore;
            callerBalanceAfter = callerBalanceBefore;
        }

        // General rule: contract_balance + caller_balance should remain the same after withdrawal
        assertTrue(contractBalanceAfter + callerBalanceAfter == contractBalanceBefore + callerBalanceBefore, "Sum of balances changed after withdrawal");
    }
}

