pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(depositAmount > 0 && depositAmount <= address(c).balance + 1e22);
        vm.assume(withdrawAmount <= depositAmount);
        vm.deal(address(this), depositAmount);
        // First deposit to have balance
        c.deposit{value: depositAmount}();
        // Get user's balance after deposit
        uint256 userBalanceAfterDeposit = address(this).balance;
        uint256 contractBalanceAfterDeposit = address(c).balance;
        // Attempt withdrawal
        uint256 gasBefore = gasleft();
        (bool success, ) = address(c).call{gas: gasleft()}(abi.encodeWithSelector(c.withdraw.selector, withdrawAmount));
        uint256 gasUsed = gasBefore - gasleft();
        // We only care about the state after a successful withdrawal
        if (success) {
            uint256 userBalanceAfter = address(this).balance;
            uint256 contractBalanceAfter = address(c).balance;
            // The invariant: contractBalance + (userETH - initialETH) == depositAmount - (withdrawAmount if deducted else 0)
            // Initial user ETH before any tx = depositAmount (we set it)
            // After deposit: userETH = depositAmount - depositAmount = 0, contract = depositAmount
            // After withdrawal: userETH = withdrawAmount (if transferred), contract = depositAmount - (withdrawAmount if deducted else 0)
            // So contractBalance + userBalance (which is now userETH after withdraw) + (depositAmount - depositAmount) = depositAmount - (deducted?)
            // Simplified: after deposit, userETH=0, contract=depositAmount. After withdraw: userETH = withdrawAmount (if transfer succeeded), contract = depositAmount - (actualDeduction)
            // The invariant: contractBalance + userBalance + (initialUserETH - depositAmount) == depositAmount - actualDeduction
            // Initial user ETH we set to depositAmount, after deposit it's 0, after withdraw it's withdrawAmount
            // So: contractBalance + userBalance == depositAmount - actualDeduction + depositAmount???
            // Better: total ETH in system = userETH + contractETH = (depositAmount - actualDeduction) + depositAmount? No.
            // Let's track: User gave depositAmount to contract, so contract has depositAmount. Then withdraw: contract sends withdrawAmount to user.
            // If deduction happens: contractBalance = depositAmount - withdrawAmount, userBalance = withdrawAmount.
            // If no deduction: contractBalance = depositAmount, userBalance = withdrawAmount.
            // So contractBalance + userBalance = depositAmount + (withdrawAmount if no deduction) or just depositAmount (if deduction).
            // Actual total depositAmount is constant. The invariant difference: Let sum = contractBalance + userBalance.
            // If deduction: sum = depositAmount. If no deduction: sum = depositAmount + withdrawAmount.
            // depositAmount is known (input). So the rule: sum - depositAmount should be 0 if deduction works, or withdrawAmount if buggy.
            uint256 sum = contractBalanceAfter + userBalanceAfter;
            assertTrue(sum - depositAmount == 0, "After withdrawal, total ETH outside the contract equals deposit amount");
        }
    }
}

