        c.migrateTo(to);
        uint256 balanceAfter = address(c).balance;
        // Reference: balanceAfter == 0; Mutant: balanceAfter == balanceBefore
        // General rule: the balanceAfter equals the balanceBefore (mutant invariant) or not (reference invariant)
        // Since we test for the mutant bug (missing transfer), we assert that balanceAfter equals balanceBefore
        assertTrue(balanceAfter == balanceBefore);
    }
}

